using System.ComponentModel.DataAnnotations; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; using OrcaFacil.Domain.Entities; using OrcaFacil.Persistence; namespace OrcaFacil.Web.Areas.Admin.Pages.KnowledgeBase; [Authorize(Policy="SuperAdmin")] public sealed class IndexModel(OrcaFacilDbContext db):PageModel { public IReadOnlyList<KnowledgeBaseArticle> Items{get;private set;}=[]; [BindProperty,Required,StringLength(180)]public string Title{get;set;}="";[BindProperty,Required,StringLength(180),RegularExpression("[a-z0-9-]+",ErrorMessage="Use letras minúsculas, números e hífens.")]public string Slug{get;set;}="";[BindProperty,Required,StringLength(500)]public string Summary{get;set;}="";[BindProperty,Required,StringLength(12000)]public string Content{get;set;}="";[BindProperty,Required,StringLength(80)]public string Category{get;set;}="Primeiros passos";[BindProperty]public string Audience{get;set;}="All";[BindProperty]public bool IsPublished{get;set;} public async Task OnGetAsync(CancellationToken ct)=>await Load(ct); public async Task<IActionResult> OnPostAsync(CancellationToken ct){if(await db.KnowledgeBaseArticles.AnyAsync(x=>x.Slug==Slug&&!x.IsDeleted,ct))ModelState.AddModelError(nameof(Slug),"Este endereço já está em uso.");if(!ModelState.IsValid){await Load(ct);return Page();}db.KnowledgeBaseArticles.Add(new(){Title=Title.Trim(),Slug=Slug.Trim(),Summary=Summary.Trim(),Content=Content.Trim(),Category=Category.Trim(),Audience=Audience,IsPublished=IsPublished,PublishedAt=IsPublished?DateTime.UtcNow:null});await db.SaveChangesAsync(ct);return RedirectToPage();}async Task Load(CancellationToken ct)=>Items=await db.KnowledgeBaseArticles.AsNoTracking().Where(x=>!x.IsDeleted).OrderBy(x=>x.DisplayOrder).ThenBy(x=>x.Title).ToListAsync(ct); }